const root = document;
const diagram = root.getElementById("diagram");
const svg = root.getElementById("connections");
const inspector = root.getElementById("inspector");
const tooltip = root.getElementById("hover-card");
let currentView = "runtime";
let selection = {type:"component",id:"session"};
let currentScenario = "search";
let currentStep = 0;

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, char => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
}

function sourceLinks(paths) {
  return `<div class="source-links">${paths.map(path => `<a href="../${escapeHtml(path)}">${escapeHtml(path)}</a>`).join("")}</div>`;
}

function componentContract(component) {
  const fields = [["Deployment",component.deploy],["Lifecycle / protocol",component.lifecycle],["Performance / service bounds",component.performance],["Throughput",component.throughput],["Configuration",component.config],["Observability",component.observe],["Failure / limitations",component.failure]];
  return `<p>${escapeHtml(component.role)}</p><dl>${fields.map(([label,value])=>`<dt>${label}</dt><dd>${escapeHtml(value)}</dd>`).join("")}</dl>${sourceLinks(component.sources)}`;
}

function inspect(type, id, announce = false) {
  selection = {type,id};
  if (type === "component") {
    const item = components[id];
    inspector.innerHTML = `<p class="eyebrow">Component${item.wip ? " · work in progress" : item.remote ? " · optional remote" : ""}</p><h3>${escapeHtml(item.name)}</h3><p class="inspector-subtitle">${escapeHtml(item.kind)}</p>${componentContract(item)}`;
  } else {
    const edge = interactions[id];
    inspector.innerHTML = `<p class="eyebrow">Interaction${edge.reply ? " · request and response" : " · one-way data/control"}</p><h3>${escapeHtml(components[edge.from].name)} → ${escapeHtml(components[edge.to].name)}</h3><dl><dt>Protocol / transport</dt><dd>${escapeHtml(edge.protocol)}</dd><dt>Payload${edge.reply ? " and response" : ""}</dt><dd>${escapeHtml(edge.data)}</dd><dt>Lifecycle / control</dt><dd>${escapeHtml(edge.control)}</dd></dl>${sourceLinks(edge.sources)}`;
  }
  highlight();
  if (announce) root.getElementById("selection-status").textContent = `Selected ${type === "component" ? components[id].name : interactions[id].label}. Details are in the inspector.`;
}

function highlight() {
  root.querySelectorAll(".node").forEach(button => {
    const id = button.dataset.id;
    const active = selection.type === "component" ? id === selection.id : [interactions[selection.id].from,interactions[selection.id].to].includes(id);
    button.classList.toggle("active",active);
    button.setAttribute("aria-pressed",String(selection.type === "component" && id === selection.id));
  });
  root.querySelectorAll("[data-edge]").forEach(element => {
    const active = selection.type === "edge" && element.dataset.edge === selection.id;
    element.classList.toggle("active",active);
    if (element.tagName === "BUTTON") element.setAttribute("aria-pressed",String(active));
  });
}

function positionTooltip(event, element) {
  const rect = element.getBoundingClientRect();
  const x = event.clientX === undefined ? rect.left + rect.width/2 : event.clientX;
  const y = event.clientY === undefined ? rect.bottom : event.clientY;
  const width = tooltip.offsetWidth;
  const height = tooltip.offsetHeight;
  tooltip.style.left = `${Math.max(12,Math.min(x+16,window.innerWidth-width-12))}px`;
  tooltip.style.top = `${Math.max(12,Math.min(y+16,window.innerHeight-height-12))}px`;
}

function showTooltip(type,id,event,element) {
  if (type === "component") {
    const item = components[id];
    tooltip.innerHTML = `<strong>${escapeHtml(item.name)}</strong><p><b>Does:</b> ${escapeHtml(item.role)}</p><p><b>Deployed:</b> ${escapeHtml(item.deploy)}</p><p>Click for lifecycle, limits, configuration and source.</p>`;
  } else {
    const edge = interactions[id];
    tooltip.innerHTML = `<strong>${escapeHtml(components[edge.from].name)} → ${escapeHtml(components[edge.to].name)}</strong><p><b>Protocol:</b> ${escapeHtml(edge.protocol)}</p><p><b>Flows:</b> ${escapeHtml(edge.data)}</p><p>Click for full control and source details.</p>`;
  }
  tooltip.hidden = false;
  element.setAttribute("aria-describedby","hover-card");
  positionTooltip(event,element);
}

function hideTooltip(element) {
  tooltip.hidden = true;
  if (element) element.removeAttribute("aria-describedby");
}

function bindInspection(element,type,id) {
  element.addEventListener("pointerenter",event=>{if(event.pointerType !== "touch") showTooltip(type,id,event,element);});
  element.addEventListener("pointermove",event=>{if(!tooltip.hidden) positionTooltip(event,element);});
  element.addEventListener("pointerleave",()=>hideTooltip(element));
  element.addEventListener("focus",event=>showTooltip(type,id,event,element));
  element.addEventListener("blur",()=>hideTooltip(element));
  element.addEventListener("click",()=>{hideTooltip(element);inspect(type,id,true);});
}

function port(position,side) {
  const [x,y] = position;
  return {N:[x+96,y],S:[x+96,y+86],W:[x,y+39],E:[x+192,y+39]}[side];
}

function drawMap(viewId) {
  currentView = viewId;
  const view = views[viewId];
  hideTooltip();
  root.querySelectorAll("[data-view]").forEach(button=>button.setAttribute("aria-selected",String(button.dataset.view===viewId)));
  root.getElementById("map-panel").setAttribute("aria-labelledby",`tab-${viewId}`);
  root.getElementById("map-description").textContent=view.description;
  diagram.style.height=`${view.height}px`;
  svg.setAttribute("viewBox",`0 0 1100 ${view.height}`);
  svg.innerHTML='<defs><marker id="arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1L7 4L1 7" fill="none" stroke="context-stroke"/></marker></defs>';
  root.getElementById("boundaries").innerHTML=view.groups.map(([name,x,y,w,h,kind])=>`<div class="boundary ${kind||""}" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px"><span class="boundary-label">${escapeHtml(name)}</span></div>`).join("");
  const nodes = root.getElementById("nodes");
  nodes.innerHTML=Object.entries(view.nodes).map(([id,[x,y]])=>{
    const item=components[id];
    return `<button type="button" class="node ${item.remote?"remote":""} ${item.wip?"wip":""} ${item.legacy?"legacy":""}" data-id="${id}" aria-pressed="false" style="left:${x}px;top:${y}px"><span class="node-kind">${escapeHtml(item.kind)}</span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.short)}</small></button>`;
  }).join("");
  nodes.querySelectorAll("button").forEach(button=>bindInspection(button,"component",button.dataset.id));
  const labels = root.getElementById("edge-labels");
  labels.replaceChildren();
  for (const [id,fromSide,toSide,via,labelPosition,fromOverride] of view.edges) {
    const edge = interactions[id];
    const from = fromOverride || edge.from;
    // The runtime map groups synthesis/file handoff under Speech; detail remains exact.
    const start=port(view.nodes[from],fromSide);
    const end=port(view.nodes[edge.to],toSide);
    const points=[start,...(via||[]),end];
    const d=points.map(([x,y],i)=>`${i?"L":"M"}${x} ${y}`).join(" ");
    const path=document.createElementNS("http://www.w3.org/2000/svg","path");
    path.setAttribute("d",d);path.setAttribute("class",`wire ${edge.remote?"remote":""}`);path.setAttribute("marker-end","url(#arrow)");path.dataset.edge=id;
    if(edge.reply) path.setAttribute("marker-start","url(#arrow)");
    svg.append(path);
    const hit=path.cloneNode();hit.setAttribute("class","wire-hit");hit.removeAttribute("marker-start");hit.removeAttribute("marker-end");hit.removeAttribute("data-edge");
    bindInspection(hit,"edge",id);svg.append(hit);
    const button=document.createElement("button");button.type="button";button.className=`edge-label ${edge.remote?"remote":""}`;button.dataset.edge=id;button.setAttribute("aria-label",`${components[edge.from].name} to ${components[edge.to].name}: ${edge.label}`);button.style.left=`${labelPosition[0]}px`;button.style.top=`${labelPosition[1]}px`;button.textContent=edge.label;
    bindInspection(button,"edge",id);labels.append(button);
  }
  highlight();highlightStep();
}

function highlightStep() {
  const step=scenarios[currentScenario][currentStep];
  root.querySelectorAll(".node").forEach(node=>node.classList.toggle("trace",[step.from,step.to].includes(node.dataset.id)));
}

function drawStep() {
  const list=scenarios[currentScenario];
  const step=list[currentStep];
  root.getElementById("steps").innerHTML=list.map((item,index)=>`<li><button type="button" data-step="${index}" ${index===currentStep?'aria-current="step"':""}>${escapeHtml(item.title)}</button></li>`).join("");
  root.querySelectorAll("[data-step]").forEach(button=>button.addEventListener("click",()=>{currentStep=Number(button.dataset.step);drawStep();}));
  root.getElementById("step-count").textContent=`${currentStep+1} / ${list.length}`;
  root.getElementById("previous").disabled=currentStep===0;
  root.getElementById("next").disabled=currentStep===list.length-1;
  root.getElementById("sequence").innerHTML=`<div class="sequence-node"><small>FROM</small><strong>${escapeHtml(components[step.from].name)}</strong></div><div class="sequence-arrow"><span>${escapeHtml(step.protocol)}</span><div class="arrow-line" aria-hidden="true"></div></div><div class="sequence-node"><small>TO</small><strong>${escapeHtml(components[step.to].name)}</strong></div>`;
  root.getElementById("step-detail").innerHTML=`<p class="eyebrow">Step ${currentStep+1}</p><h3>${escapeHtml(step.title)}</h3><dl class="step-fields"><div><dt>Input</dt><dd>${escapeHtml(step.input)}</dd></div><div><dt>Output</dt><dd>${escapeHtml(step.output)}</dd></div></dl><p>${escapeHtml(step.state)}</p><button type="button" id="inspect-step">Inspect this contract ↑</button>`;
  root.getElementById("inspect-step").addEventListener("click",()=>{
    const matching=Object.entries(views).find(([,view])=>view.edges.some(([id])=>id===step.edge));
    const currentHas=views[currentView].edges.some(([id])=>id===step.edge);
    if(!currentHas && matching) drawMap(matching[0]);
    inspect("edge",step.edge,true);
    root.getElementById("architecture").scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});
  });
  highlightStep();
}

root.getElementById("module-catalogue").innerHTML=Object.entries(components).map(([id,item])=>`<details class="module" id="module-${id}"><summary>${escapeHtml(item.name)}${item.wip?" · WIP":""}<small>${escapeHtml(item.kind)}</small></summary><div class="module-content">${componentContract(item)}</div></details>`).join("");
root.getElementById("heads-table").innerHTML=heads.map(([name,tools,backend])=>`<tr><td>${escapeHtml(name)}</td><td><code>${escapeHtml(tools)}</code></td><td>${escapeHtml(backend)}</td></tr>`).join("");
root.getElementById("protocol-table").innerHTML=Object.entries(interactions).map(([id,edge])=>`<tr><td><button type="button" data-contract="${id}">${escapeHtml(components[edge.from].name)} → ${escapeHtml(components[edge.to].name)}</button></td><td>${escapeHtml(edge.protocol)}</td><td>${escapeHtml(edge.data)}<br><br>${escapeHtml(edge.control)}</td></tr>`).join("");
root.querySelectorAll("[data-contract]").forEach(button=>button.addEventListener("click",()=>{inspect("edge",button.dataset.contract,true);inspector.scrollIntoView({block:"nearest"});}));
root.querySelectorAll("[data-view]").forEach(button=>button.addEventListener("click",()=>drawMap(button.dataset.view)));
root.getElementById("map-tabs").addEventListener("keydown",event=>{
  if(!["ArrowLeft","ArrowRight","Home","End"].includes(event.key)) return;
  const buttons=Array.from(root.querySelectorAll("[data-view]"));
  const index=buttons.indexOf(document.activeElement);
  if(index<0) return;
  event.preventDefault();
  const next=event.key==="Home"?0:event.key==="End"?buttons.length-1:(index+(event.key==="ArrowRight"?1:-1)+buttons.length)%buttons.length;
  buttons[next].focus();drawMap(buttons[next].dataset.view);
});
root.getElementById("scenario").addEventListener("change",event=>{
  currentScenario=event.target.value;currentStep=0;
  drawMap(currentScenario==="recognition"?"audio":currentScenario==="followup"?"tools":"runtime");drawStep();
});
root.getElementById("previous").addEventListener("click",()=>{if(currentStep>0){currentStep--;drawStep();}});
root.getElementById("next").addEventListener("click",()=>{if(currentStep<scenarios[currentScenario].length-1){currentStep++;drawStep();}});
root.addEventListener("keydown",event=>{if(event.key==="Escape") hideTooltip();});
window.addEventListener("scroll",()=>hideTooltip(),true);
window.addEventListener("resize",()=>hideTooltip());
drawMap("runtime");inspect("component","session");drawStep();
